'use strict';
(()=>{
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',book:'<path d="M3 4h6c2 0 3 1 3 2v15c0-2-2-3-4-3H3ZM21 4h-6c-2 0-3 1-3 2v15c0-2 2-3 4-3h5Z"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V8m5 8V4"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 2 4v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',audio:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12H3v7h4v-7Zm16 0h1v7h-4v-7Z"/>',video:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m10 8 6 4-6 4Z"/>',check:'<path d="m5 12 4 4L20 5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',leaf:'<path d="M20 3C9 2 3 8 5 15c2 7 14 5 15-12ZM4 21 15 10"/>',layers:'<path d="m3 8 9-5 9 5-9 5Zm0 5 9 5 9-5M3 18l9 5 9-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.book}</svg>`;
let resources=[];
let portalAccess={status:"loading",training:false,community:false,admin:false,catalogReady:false};
const routeResources=['despegue-spotify','guia-inicio','siglo-xxi','como-contactar'];
const key='lebenar.educacion.v1';
let state={completed:[],saved:[],days:[],notes:{},last:null};let storageAvailable=true;let toastTimer;let query='';let filter='todos';let progressTab='guardados';let communityTab='novedades';
const ids=new Set(['despegue-spotify','despegue-youtube','guia-inicio','siglo-xxi','biblioteca','como-contactar','lista-profesional']);
try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&typeof raw==='object'){state.completed=Array.isArray(raw.completed)?[...new Set(raw.completed.filter(x=>ids.has(x)))]:[];state.saved=Array.isArray(raw.saved)?[...new Set(raw.saved.filter(x=>ids.has(x)))]:[];state.days=Array.isArray(raw.days)?[...new Set(raw.days.filter(x=>Number.isInteger(x)&&x>0&&x<=30))]:[];state.notes=raw.notes&&typeof raw.notes==='object'&&!Array.isArray(raw.notes)?raw.notes:{};state.last=ids.has(raw.last)?raw.last:null;}}catch{storageAvailable=false;}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let accountController=null;
function persist(){if(!portalAccess.training||!portalAccess.catalogReady)return true;if(accountController?.save(JSON.parse(JSON.stringify(state))))return true;try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{storageAvailable=false;notify('Tu navegador no permite guardar. El progreso durará esta sesión.');return false;}}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function done(id){return state.completed.includes(id)}
function saved(id){return state.saved.includes(id)}
function bookmark(r){return `<button class="bookmark ${saved(r.id)?'active':''}" data-save="${r.id}" aria-label="${saved(r.id)?'Quitar de guardados':'Guardar'}: ${r.title}" aria-pressed="${saved(r.id)}">${icon('bookmark')}</button>`}
function card(r){return `<article class="resource-card"><div class="resource-cover ${r.type}"><div class="cover-icon">${icon(r.type==='biblioteca'?'layers':r.type==='lectura'?'book':r.type)}</div><span class="cover-word">${r.cover}</span>${bookmark(r)}</div><div class="resource-body"><span class="tag">${r.format}</span><h3><a href="#recurso/${r.id}">${r.title}</a></h3><p>${r.description}</p><div class="resource-bottom"><a href="#recurso/${r.id}" aria-label="Explorar ${r.title}">Explorar recurso ↗</a>${done(r.id)?`<span class="done-badge">${icon('check')}Completado</span>`:`<span>${r.step}</span>`}</div></div></article>`}
function heading(eyebrow,title,description,back=''){return `<div class="page-heading">${back?`<a class="back" href="${back}">← Volver a los recursos</a>`:''}<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>`}
function updateTopProgress(){document.querySelector('#top-progress').innerHTML=`Mi progreso <span>${state.completed.length}</span>`;}
const journeys=[
 {title:'Quiero conocer el proyecto',tag:'Descubrí la propuesta',description:'Conversá con Leonel para conocer la propuesta y resolver tus primeras dudas.',href:'#contacto',cta:'Conversar con Leonel',alt:'Brújula dorada para descubrir el proyecto'},
 {title:'Estoy empezando',tag:'Dale dirección a tu primer paso',description:'Seguí un recorrido con Despegue 30D, la guía de inicio y tu primera lectura.',href:'#primeros-pasos',cta:'Empezar mi recorrido',alt:'Libro abierto para iniciar la formación'},
 {title:'Ya soy socio',tag:'Aprendé, practicá y compartí',description:'Retomá tu formación, trabajá tus conversaciones y organizá tu próxima acción.',href:'#socios',cta:'Entrar al espacio de socios',alt:'Personas en equipo para retomar el aprendizaje'}
];
let carouselIndex=1;
function journeyArt(i){const shape=[`<circle cx="190" cy="82" r="45"/><path d="m214 58-12 36-36 12 12-36Z"/>`,`<path d="M133 49h42q15 0 15 12v57q-7-10-20-10h-37ZM247 49h-42q-15 0-15 12v57q7-10 20-10h37Z"/><path d="M150 65h22m-22 14h22m36-14h22m-22 14h22"/>`,`<circle cx="174" cy="61" r="18"/><path d="M139 123v-13q0-25 35-25t35 25v13m6-74a18 18 0 0 1 0 34m17 14q16 6 16 26"/>`][i];return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="382" height="164" viewBox="0 0 382 164"><defs><radialGradient id="g"><stop stop-color="${['#286064','#374f54','#554a30'][i]}"/><stop offset="1" stop-color="#081C29"/></radialGradient></defs><rect width="382" height="164" fill="url(#g)"/><g stroke="#76B9BB" opacity=".16" fill="none"><circle cx="190" cy="82" r="70"/><path d="M0 82h382M190 0v164"/></g><g stroke="#D6B66C" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none">${shape}</g></svg>`);}
function carouselMarkup(){return `<div class="journey-carousel" role="region" aria-roledescription="carrusel" aria-label="Elegí tu camino"><p class="sr-only" id="carousel-instructions">Tres opciones. Usá las flechas, los indicadores o las teclas izquierda y derecha. También podés deslizar o arrastrar las tarjetas.</p><div class="carousel-stage" id="journey-stage" tabindex="0" aria-label="Tarjetas de caminos" aria-describedby="carousel-instructions">${journeys.map((j,i)=>`<article class="journey-card" data-slide="${i}" data-position="${i===carouselIndex?'active':i<carouselIndex?'prev':'next'}" role="group" aria-roledescription="diapositiva" aria-label="${i+1} de 3: ${j.title}"><div class="journey-picture"><img src="${journeyArt(i)}" alt="${j.alt}" width="382" height="164" draggable="false"><span class="journey-index">0${i+1} / 03</span></div><div class="journey-body"><span class="journey-tag">${j.tag}</span><h3>${j.title}</h3><p>${j.description}</p><a class="btn" href="${j.href}">${j.cta} ${icon('arrow')}</a></div></article>`).join('')}</div><div class="carousel-controlbar"><button class="carousel-arrow prev" data-carousel-move="-1" aria-label="Camino anterior">${icon('arrow')}</button><div class="carousel-dots" aria-label="Elegir una opción">${journeys.map((j,i)=>`<button class="carousel-dot" data-carousel-dot="${i}" aria-label="Mostrar ${j.title}" aria-pressed="${i===carouselIndex}"></button>`).join('')}</div><button class="carousel-arrow" data-carousel-move="1" aria-label="Camino siguiente">${icon('arrow')}</button></div><p class="carousel-caption" id="carousel-caption" aria-live="polite" aria-atomic="true">${carouselIndex+1} de 3 · ${journeys[carouselIndex].title}</p></div>`}
function initCarousel(){
 const stage=document.querySelector('#journey-stage');if(!stage)return;
 const root=stage.closest('.journey-carousel');
 function choose(index){
  carouselIndex=(index+journeys.length)%journeys.length;
  stage.querySelectorAll('[data-slide]').forEach(card=>{const i=Number(card.dataset.slide);card.dataset.position=i===carouselIndex?'active':i===(carouselIndex+2)%3?'prev':'next';});
  root.querySelectorAll('[data-carousel-dot]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.carouselDot)===carouselIndex)));
  root.querySelector('#carousel-caption').textContent=`${carouselIndex+1} de 3 · ${journeys[carouselIndex].title}`;
 }
 root.querySelectorAll('[data-carousel-move]').forEach(button=>button.addEventListener('click',()=>choose(carouselIndex+Number(button.dataset.carouselMove))));
 root.querySelectorAll('[data-carousel-dot]').forEach(button=>button.addEventListener('click',()=>choose(Number(button.dataset.carouselDot))));
 root.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();choose(carouselIndex+(event.key==='ArrowRight'?1:-1));}else if(event.key==='Home'||event.key==='End'){event.preventDefault();choose(event.key==='Home'?0:2);}});
 let pointerInteraction=false;root.addEventListener('pointerdown',()=>{pointerInteraction=true;},true);root.addEventListener('keydown',()=>{pointerInteraction=false;},true);stage.addEventListener('focusin',event=>{const card=event.target.closest('[data-slide]');if(card&&!pointerInteraction)choose(Number(card.dataset.slide));});
 let drag=null,suppressClick=false;
 stage.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('a,button'))return;drag={id:event.pointerId,x:event.clientX,y:event.clientY};stage.setPointerCapture(event.pointerId);});
 stage.addEventListener('pointermove',event=>{if(!drag||drag.id!==event.pointerId)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)){stage.dataset.dragging='true';stage.style.setProperty('--drag-offset',`${Math.max(-45,Math.min(45,dx/3))}px`);}});
 function stopDrag(event,cancelled=false){if(!drag||drag.id!==event.pointerId)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;const moved=Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy);if(!cancelled&&moved){choose(carouselIndex+(dx<0?1:-1));suppressClick=true;setTimeout(()=>{suppressClick=false;},0);}drag=null;stage.dataset.dragging='false';stage.style.removeProperty('--drag-offset');if(stage.hasPointerCapture(event.pointerId))stage.releasePointerCapture(event.pointerId);}
 stage.addEventListener('pointerup',event=>stopDrag(event));
 stage.addEventListener('pointercancel',event=>stopDrag(event,true));
 stage.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopPropagation();return;}const card=event.target.closest('[data-slide]');if(card&&!event.target.closest('a,button'))choose(Number(card.dataset.slide));},true);
 choose(carouselIndex);
}
function home(){const next=resources.find(r=>r.id===state.last&&!done(r.id))||resources.find(r=>routeResources.includes(r.id)&&!done(r.id))||resources[0]||{id:'despegue-spotify',title:'Tu entrenamiento de 30 días'};return `<section class="welcome-hero"><div class="welcome-copy"><div class="eyebrow">CRECER AYUDANDO A CRECER</div><h1 class="welcome-title">Aprender.<br>Emprender. <span>Crecer.</span></h1><p class="welcome-lead">Ideas y herramientas para dar tu próximo paso y crecer en equipo.</p><div class="button-row"><button class="btn btn-gold" data-find-path>Elegir mi camino ${icon('arrow')}</button><a class="quiet-link" href="#recursos">Ver recursos ↗</a></div></div><figure class="welcome-picture"><img src="assets/images/bienvenida-equipo.webp" alt="Escena ilustrativa de cuatro adultos aprendiendo y compartiendo ideas alrededor de una mesa" width="1672" height="941" fetchpriority="high"><figcaption>Escena ilustrativa creada con IA</figcaption></figure></section><p class="scene-label">Escena ilustrativa creada con IA</p><nav class="resource-strip" aria-label="Accesos rápidos de formación"><a href="#recurso/despegue-spotify">${icon('audio')}<span><strong>Escuchá</strong><small>Audios del entrenamiento</small></span></a><a href="#recurso/despegue-youtube">${icon('video')}<span><strong>Mirá</strong><small>Videos del entrenamiento</small></span></a><a href="#recurso/biblioteca">${icon('book')}<span><strong>Leé</strong><small>Biblioteca autorizada</small></span></a></nav><section class="journeys" aria-labelledby="path-title"><div class="section-head"><div><h2 id="path-title" tabindex="-1">Un camino para tu momento.</h2><p>Elegí por dónde empezar. Siempre podés cambiar de rumbo.</p></div><span class="journey-hint">${icon('arrow')}Deslizá para explorar</span></div>${carouselMarkup()}</section><section class="recommendation"><div><div class="eyebrow">${state.last?'RETOMÁ TU RECORRIDO':'UNA IDEA PARA EMPEZAR'}</div><h3>${next.title}</h3><p>${state.last?'Volvé a la formación y seguí desde tu próximo paso.':'Un audio, una idea y una acción concreta. Empezá a tu ritmo.'}</p></div><a class="btn btn-white" href="#recurso/${next.id}">${state.last?'Continuar aprendiendo':'Conocer Despegue 30D'} ${icon('arrow')}</a></section><blockquote class="quote">El crecimiento cobra otro sentido cuando también ayuda a alguien más.<small>EL ESPÍRITU DE LEBENAR®</small></blockquote>`}
function project(){return `${heading('CONVERSEMOS','Conocé la propuesta con Leonel.','Contame qué estás buscando y conversemos sobre el proyecto.')}<section class="panel"><h2>Un primer contacto, sin compromiso.</h2><p>Podés escribir a la cuenta de LEBENAR® para conocer la propuesta y consultar por tu acceso a la formación.</p><a class="btn btn-gold" href="mailto:lebenar.business@gmail.com?subject=Quiero%20conocer%20la%20propuesta%20LEBENAR">Escribir a Leonel ${icon('arrow')}</a><p class="small-note">El acceso directo por WhatsApp se habilitará cuando Leonel confirme su número de contacto.</p></section>`;}
function accessPage(){return `${heading('ACCESO AUTORIZADO','Un espacio para crecer juntos.','Ingresá con Google. Leonel debe aprobar tu cuenta antes de que puedas abrir los materiales.')}<section class="panel" id="access-app"><p>Comprobando tu acceso…</p></section>`;}
function routeSteps(){return routeResources.map((id,i)=>{const r=resources.find(x=>x.id===id);return `<a href="#recurso/${id}" class="step-row ${done(id)?'complete':''}"><span class="step-n">${done(id)?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${r.title}</strong><small>${r.format} · ${done(id)?'Completado':'A tu ritmo'}</small></span>${icon('arrow')}</a>`}).join('')}
function daysPanel(){return `<section class="panel"><div class="eyebrow">TU HÁBITO DE APRENDIZAJE</div><h2>Un paso cada día.</h2><p>Usá este registro junto a Despegue / Inicio 30D. Marcá un día después de escuchar y reflexionar.</p><div class="meter"><span style="width:${state.days.length/30*100}%"></span></div><p class="small-note" id="day-count">${state.days.length} de 30 días registrados</p><div class="day-grid">${Array.from({length:30},(_,i)=>`<button class="day ${state.days.includes(i+1)?'active':''}" data-day="${i+1}" aria-label="Día ${i+1}" aria-pressed="${state.days.includes(i+1)}">${i+1}</button>`).join('')}</div><p class="small-note">Tu registro es personal y no se sincroniza con Spotify o YouTube. Podés desmarcar cualquier día.</p><a href="#recurso/despegue-spotify" class="btn btn-text">Ir a Despegue 30D ${icon('arrow')}</a></section>`}
function notesPanel(id,label,placeholder){return `<label class="note-label" for="note-${id}">${label}</label><textarea class="notes" id="note-${id}" data-note="${id}" maxlength="3000" placeholder="${placeholder}">${escapeHTML(state.notes[id]||'')}</textarea><div class="save-status" id="status-${id}" aria-live="polite">${storageAvailable?'Se guarda automáticamente en este navegador.':'Guardado temporal: no hay almacenamiento disponible.'}</div>`}
function firstSteps(){return `${heading('TU PUNTO DE PARTIDA','Empezá con algo pequeño.','Escuchá, leé y llevá una idea a la práctica. Este orden es una propuesta: podés volver, elegir otro formato y avanzar a tu ritmo.')}<div class="two-col"><div><div class="step-list">${routeSteps()}</div><section class="panel"><div class="eyebrow">ANTES DE EMPEZAR</div><h2>¿Para qué querés crecer?</h2><p>Dale una dirección a tu aprendizaje. Pensá qué te gustaría mejorar y cuál podría ser tu primer paso esta semana.</p>${notesPanel('proposito','Mi propósito y mi próximo paso','Quiero aprender a… Esta semana voy a…')}</section><div class="notice">¿Preferís mirar? La playlist de Despegue 30D también está en <a href="#recurso/despegue-youtube"><u>YouTube ↗</u></a>.</div></div>${daysPanel()}</div>`}
function catalog(){return `${heading('APRENDÉ A TU MANERA','Un recurso. Una nueva idea.','Audios para escuchar, videos para explorar y lecturas para profundizar. Elegí lo que te ayuda a avanzar hoy.')}<section aria-label="Catálogo de recursos"><div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">Buscar recursos</span><input id="search-resources" type="search" placeholder="Buscar por tema, título o autor" value="${escapeHTML(query)}" autocomplete="off"></label><div class="filter-buttons" aria-label="Filtrar por formato">${[['todos','Todos'],['audio','Audios'],['video','Videos'],['lectura','Lecturas'],['biblioteca','Biblioteca']].map(([id,label])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div></div><div id="catalog-results"></div></section><div class="notice">Los recursos se abren en su plataforma original. Los archivos de Google conservan sus permisos; Spotify y YouTube pueden solicitar una cuenta. Consultá el estado de comprobación dentro de cada recurso.</div>`}
function updateCatalog(){const list=resources.filter(r=>(filter==='todos'||r.type===filter)&&normalize(`${r.title} ${r.description} ${r.format} ${r.source}`).includes(normalize(query)));document.querySelector('#catalog-results').innerHTML=`<p class="resource-count" role="status">${list.length} ${list.length===1?'recurso disponible':'recursos disponibles'}${query?' para tu búsqueda':''}</p><div class="resource-grid">${list.length?list.map(card).join(''):'<div class="empty"><h3>No encontramos ese recurso.</h3><p>Probá otra palabra o elegí otro formato.</p><button class="btn btn-text" data-clear-search>Ver todos los recursos →</button></div>'}</div>`;}
function detail(id){const r=resources.find(x=>x.id===id);if(!r)return `${heading('ESTE CAMINO NO EXISTE','Volvamos a encontrarnos.','El recurso que buscás no forma parte de esta selección.')}<a class="btn btn-dark" href="#recursos">Explorar recursos</a>`;const index=resources.indexOf(r);return `${heading(r.step,r.title,r.description,'#recursos')}<div class="two-col"><div><div class="detail-cover ${r.type}">${icon(r.type==='biblioteca'?'layers':r.type==='lectura'?'book':r.type)}<span class="cover-word">${r.cover}</span></div><div class="detail-meta"><span>${r.format}</span><span>Acceso gratuito · plataforma externa</span></div><section class="panel"><h2>Hacé espacio para aprender.</h2><p>${r.purpose}</p><div class="button-row detail-actions"><a class="btn btn-dark" href="${r.url}" target="_blank" rel="noopener noreferrer" data-open="${r.id}">Abrir ${r.type==='biblioteca'?'biblioteca':'recurso'} ${icon('up')}</a><button class="btn btn-light" data-complete="${r.id}" aria-pressed="${done(r.id)}">${icon('check')}${done(r.id)?'Completado · desmarcar':'Marcar como completado'}</button></div><p class="small-note">Se abre en otra pestaña para que puedas volver y continuar acá. La apertura no marca el recurso como completado.</p>${notesPanel(r.id,'Una idea que me llevo…','¿Qué aprendiste? ¿Cómo podrías aplicarlo?')}</section><nav class="resource-nav" aria-label="Avanzar entre recursos">${index>0?`<a href="#recurso/${resources[index-1].id}"><small>← ANTERIOR</small>${resources[index-1].title}</a>`:'<a href="#primeros-pasos"><small>← VOLVER</small>Mi recorrido inicial</a>'}${index<resources.length-1?`<a href="#recurso/${resources[index+1].id}"><small>SIGUIENTE →</small>${resources[index+1].title}</a>`:'<a href="#progreso"><small>SEGUIR →</small>Ver mi progreso</a>'}</nav></div><aside><section class="panel"><div class="eyebrow">FICHA DEL RECURSO</div><h3>De dónde viene</h3><p>${r.source}</p>${r.context?`<p class="external-note">${r.context}</p>`:''}<details open><summary>Estado del enlace</summary><p>${r.verification}</p></details><details><summary>¿No podés abrirlo?</summary><p>Iniciá sesión en la plataforma de origen si lo solicita. Si el archivo pide permiso, solicitáselo a su propietario. LEBENAR® conserva los accesos originales.</p></details><div class="button-row"><button class="btn btn-light" data-save="${r.id}" aria-pressed="${saved(r.id)}">${icon('bookmark')}${saved(r.id)?'Quitar de guardados':'Guardar para después'}</button></div></section><div class="notice">LEBENAR® es la marca personal de Leonel Benítez. Los recursos de terceros mantienen su autoría y su contexto. No constituyen promesas de resultados económicos.</div></aside></div>`}
function progress(){const list=resources.filter(r=>progressTab==='guardados'?saved(r.id):done(r.id));return `${heading('TU RECORRIDO','Cada paso cuenta.','Volvé a tus recursos, revisá tus ideas y reconocé lo que ya avanzaste.')}<section class="panel" data-account-panel style="margin-bottom:24px"><p>Cargando acceso personal…</p></section><div class="progress-summary"><div class="stat"><strong>${state.completed.length}<small style="font:14px sans-serif;color:#7d8f81"> / ${resources.length}</small></strong><span>Recursos completados</span></div><div class="stat"><strong>${state.saved.length}</strong><span>Guardados para después</span></div><div class="stat"><strong>${state.days.length}<small style="font:14px sans-serif;color:#7d8f81"> / 30</small></strong><span>Días de aprendizaje</span></div></div><div class="tabs-row" aria-label="Ver recursos personales">${[['guardados','Mis guardados'],['completados','Completados']].map(([id,title])=>`<button class="tab ${progressTab===id?'active':''}" data-progress-tab="${id}" aria-pressed="${progressTab===id}">${title}</button>`).join('')}</div><div class="resource-grid">${list.length?list.map(card).join(''):`<div class="empty">${icon(progressTab==='guardados'?'bookmark':'compass')}<h3 style="margin-top:15px">${progressTab==='guardados'?'Tu próxima idea puede estar a un clic.':'Tu primer paso te espera.'}</h3><p>${progressTab==='guardados'?'Usá el marcador de cualquier recurso para encontrarlo acá.':'Marcá un recurso como completado después de trabajarlo.'}</p><a class="btn btn-text" href="#recursos">Explorar recursos →</a></div>`}</div><div class="two-col" style="margin-top:25px"><section class="panel"><h2>Tu propósito sigue acá.</h2>${notesPanel('proposito','Mi propósito y mi próximo paso','Quiero aprender a… Esta semana voy a…')}<div class="notice">${accountController?.signedIn()?'Tu avance se guarda en tu cuenta. Consultá el estado de guardado arriba.':storageAvailable?'Sin iniciar sesión, tu avance queda solo en este navegador.':'Este navegador no permite guardar: tus avances durarán solo esta sesión.'}</div><button class="btn btn-text" data-reset>Reiniciar mi recorrido</button></section>${daysPanel()}</div>`}
function community(){return `${heading('COMUNIDAD LEBENAR®','Crecer también es compartir.','Un espacio de encuentro para los socios autorizados.')}<section class="panel" data-community-root><p>Cargando la comunidad…</p></section><div class="button-row"><a class="btn btn-light" href="#primeros-pasos">Mi entrenamiento 30D</a><a class="btn btn-light" href="#recursos">Biblioteca y recursos</a></div>`;}
function continuing(){return `${heading('ESPACIO DE SOCIOS Y APRENDIZAJE','Seguí creciendo, en equipo.','Si ya empezaste, elegí una herramienta para practicar o retomá tu recorrido. Este espacio reúne formación; no administra tu condición de socio de ninguna empresa.')}<section class="panel" data-account-panel style="margin-bottom:24px"><p>Cargando acceso personal…</p></section><section class="portal-teaser panel"><div class="community-mark">${icon('users')}</div><div><div class="eyebrow">COMUNIDAD LEBENAR®</div><h2>Tu espacio en equipo.</h2><p>Novedades, formación, recursos y encuentros, reunidos en un portal de socios.</p><span class="portal-preview-label">Solo para socios autorizados</span></div><a class="btn btn-gold" href="#comunidad">Entrar a la comunidad ${icon('arrow')}</a></section><div class="recommendation" style="margin-bottom:27px"><div><div class="eyebrow">DALE CONTINUIDAD</div><h3>Aprender. Practicar. Compartir.</h3><p>Elegí una idea, ponela a prueba y conversá lo aprendido con tu equipo.</p></div><a class="btn btn-dark" href="#progreso">Ver mi progreso ${icon('arrow')}</a></div><div class="resource-grid">${['como-contactar','lista-profesional','biblioteca'].map(id=>card(resources.find(r=>r.id===id))).join('')}</div><section class="panel" style="margin-top:25px"><div class="eyebrow">UNA ACCIÓN CONCRETA</div><h2>¿Qué vas a poner en práctica?</h2><p>Un aprendizaje se vuelve más útil cuando encuentra un lugar en tu semana.</p>${notesPanel('accion','Mi próxima acción','Esta semana voy a practicar…')}</section>`}
function about(){return `${heading('LA MARCA PERSONAL','Crecer ayudando a crecer.','Un espacio de Leonel Benítez para aprender, emprender y acompañar el crecimiento de otras personas.')}<section class="about-hero"><img src="assets/images/logo-lebenar.webp" alt="Emblema de LEBENAR®" width="130" height="130"><div><h2>El aprendizaje como punto de encuentro.</h2><p>LEBENAR® reúne recursos de formación y propone un camino sencillo: descubrir una idea, llevarla a la práctica y compartir lo aprendido. Cada persona elige su ritmo y su dirección.</p></div></section><div class="about-grid"><section class="panel"><div class="eyebrow">IDENTIDAD PROPIA</div><h3>Una marca, una visión.</h3><p>LEBENAR® es la marca personal de Leonel Benítez. Esta plataforma tiene una identidad propia, separada de las empresas con las que pueda desarrollar actividades comerciales.</p><p>Amway es una empresa asociada a su actividad como distribuidor independiente. LEBENAR® no es Amway ni su sitio oficial. La guía de inicio y algunos audios proceden de un equipo vinculado a esa actividad.</p></section><section class="panel"><div class="eyebrow">RECURSOS CON CONTEXTO</div><h3>Aprender con criterio.</h3><p>Los materiales externos conservan sus autores, opiniones y plataformas de origen. Acceder a la formación no implica contratar, registrarse en una empresa ni realizar una compra.</p><p>El acceso a esta selección es gratuito para las personas autorizadas. Algunas plataformas pueden pedir una cuenta o permisos de su propietario. No se ofrecen garantías de ingresos ni resultados.</p></section></div><section class="panel" style="margin-top:22px"><h2>Así funciona este espacio</h2><details><summary>¿Por dónde empiezo?</summary><p>El recorrido de Primeros pasos te propone Despegue 30D, una guía, una lectura y un audio. También podés explorar libremente el catálogo.</p></details><details><summary>¿Qué significa completar un recurso?</summary><p>Es un registro que marcás vos después de trabajarlo. No verifica reproducción, no otorga una certificación y podés desmarcarlo.</p></details><details><summary>¿Dónde se guarda mi información?</summary><p>Con Google y acceso autorizado, el avance se guarda en tu cuenta mediante Firebase para recuperarlo en otros dispositivos. Importar el avance local es opcional. Podés reiniciarlo desde Mi progreso.</p></details><details><summary>¿Quién puede ver esta versión?</summary><p>La portada es pública. Todo el entrenamiento y sus materiales requieren ingreso con Google y aprobación de Leonel. La comunidad requiere además el perfil de socio. Los archivos externos conservan sus permisos de origen.</p></details><div class="button-row" style="margin-top:20px"><a class="btn btn-dark" href="#primeros-pasos">Dar mi primer paso ${icon('arrow')}</a><a class="btn btn-light" href="#recursos">Explorar la selección</a></div></section>`}
const main=document.querySelector('main');
function render({focus=true,scroll=true}={}){const hash=location.hash.slice(1)||'inicio';const [route,id]=hash.split('/');document.body.dataset.page=route;const names={contacto:'Conocé la propuesta',acceso:'Mi cuenta',administracion:'Administrar accesos',inicio:'Tu espacio para crecer','primeros-pasos':'Primeros pasos',socios:'Seguir creciendo',comunidad:'Comunidad de socios',recursos:'Recursos de formación',progreso:'Mi progreso',proyecto:'Conocer el proyecto',acerca:'Acerca de LEBENAR®',recurso:'Recursos de formación'};document.querySelector('#breadcrumb').textContent=names[route]||'Tu espacio para crecer';document.title=`${names[route]||'Inicio'} · LEBENAR®`;const navRoute=['socios','comunidad'].includes(route)?'socios':['primeros-pasos','recurso'].includes(route)?'recursos':route;const nav=[['inicio','home','Inicio'],['contacto','compass','La propuesta'],['recursos','book','Formación'],['socios','users','Socios'],['acceso','chart','Mi cuenta']];if(portalAccess.admin)nav.push(['administracion','users','Administrar accesos']);const navigation=nav.map(([r,i,t])=>`<a href="#${r}" ${r===navRoute?'class="active" aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('');document.querySelector('#nav').innerHTML=navigation;const dockRoute=['socios','comunidad'].includes(route)?'socios':navRoute;document.querySelector('#app-dock').innerHTML=[['inicio','home','Inicio'],['recursos','book','Formación'],['socios','users','Socios'],['progreso','chart','Mi progreso']].map(([r,i,t])=>`<a href="#${r}" ${r===dockRoute?'class="active" aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('');const restricted=!['inicio','contacto','proyecto','acerca','acceso','administracion'].includes(route);const blocked=restricted&&(!portalAccess.training||!portalAccess.catalogReady||(['socios','comunidad'].includes(route)&&!portalAccess.community));main.innerHTML=blocked||['acceso','administracion'].includes(route)?accessPage():route==='contacto'?project():route==='inicio'?home():route==='primeros-pasos'?firstSteps():route==='recursos'?catalog():route==='progreso'?progress():route==='socios'?continuing():route==='comunidad'?community():route==='proyecto'?project():route==='acerca'?about():route==='recurso'?detail(id):`${heading('VOLVER A EMPEZAR','Encontrá tu camino.','Esta sección no está disponible. Volvé al inicio para continuar.')}<a class="btn btn-dark" href="#inicio">Ir a la bienvenida</a>`;accountController?.panel();if(route==='recursos'&&!blocked)updateCatalog();if(route==='inicio')initCarousel();window.lebenarPortal?.mount?.();updateTopProgress();if(scroll)window.scrollTo({top:0,behavior:'instant'});if(focus)main.focus({preventScroll:true});document.querySelector('.sidebar').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelector('.menu-toggle').setAttribute('aria-label','Abrir menú');}
document.addEventListener('click',event=>{if(event.target.closest('[data-google-login]')){accountController?accountController.login():notify('El acceso está cargando. Intentá nuevamente.');return;}const communityChoice=event.target.closest('[data-community-tab]');if(communityChoice){communityTab=communityChoice.dataset.communityTab;render({focus:false,scroll:false});document.querySelector(`[data-community-tab="${communityTab}"]`)?.focus({preventScroll:true});return;}if(event.target.closest('a[href="#contenido"]')){event.preventDefault();main.focus();return;}if(event.target.closest('[data-find-path]')){const title=document.querySelector('#path-title');title.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});title.focus({preventScroll:true});return;}const save=event.target.closest('[data-save]');if(save){const id=save.dataset.save;state.saved=saved(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();const wasSaved=saved(id);render({focus:false,scroll:false});const focusTarget=document.querySelector(`[data-save="${id}"]`);focusTarget?.focus({preventScroll:true});notify(wasSaved?'Recurso guardado para después.':'Recurso quitado de guardados.');return;}const complete=event.target.closest('[data-complete]');if(complete){const id=complete.dataset.complete;state.completed=done(id)?state.completed.filter(x=>x!==id):[...state.completed,id];persist();const isDone=done(id);render({focus:false,scroll:false});document.querySelector(`[data-complete="${id}"]`)?.focus({preventScroll:true});notify(isDone?'Un paso más en tu recorrido.':'Podés volver a trabajar este recurso.');return;}const day=event.target.closest('[data-day]');if(day){const d=Number(day.dataset.day);state.days=state.days.includes(d)?state.days.filter(x=>x!==d):[...state.days,d];persist();day.classList.toggle('active',state.days.includes(d));day.setAttribute('aria-pressed',String(state.days.includes(d)));document.querySelector('#day-count').textContent=`${state.days.length} de 30 días registrados`;document.querySelectorAll('.meter span').forEach(el=>el.style.width=`${state.days.length/30*100}%`);if(location.hash==='#progreso'){const stats=document.querySelectorAll('.stat strong');stats[2].innerHTML=`${state.days.length}<small style="font:14px sans-serif;color:#7d8f81"> / 30</small>`;}return;}const f=event.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.filter===filter);el.setAttribute('aria-pressed',String(el.dataset.filter===filter));});updateCatalog();return;}if(event.target.closest('[data-clear-search]')){query='';filter='todos';render({focus:false,scroll:false});document.querySelector('#search-resources').focus();return;}const tab=event.target.closest('[data-progress-tab]');if(tab){progressTab=tab.dataset.progressTab;render({focus:false,scroll:false});document.querySelector(`[data-progress-tab="${progressTab}"]`).focus({preventScroll:true});return;}const open=event.target.closest('[data-open]');if(open){state.last=open.dataset.open;persist();return;}if(event.target.closest('[data-reset]'))document.querySelector('#reset-dialog').showModal();});
document.addEventListener('input',event=>{if(event.target.id==='search-resources'){query=event.target.value;updateCatalog();}if(event.target.matches('[data-note]')){const id=event.target.dataset.note;state.notes[id]=event.target.value;const ok=persist();document.querySelector(`#status-${id}`).textContent=accountController?.signedIn()?'Guardado en cuenta pendiente de confirmación.':ok?'Guardado en este navegador.':'Guardado temporal: solo durante esta sesión.';}});
document.querySelector('.menu-toggle').addEventListener('click',()=>{const open=document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded',String(open));document.querySelector('.menu-toggle').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');});
document.querySelector('#cancel-reset').addEventListener('click',()=>document.querySelector('#reset-dialog').close());
document.querySelector('#confirm-reset').addEventListener('click',()=>{state={completed:[],saved:[],days:[],notes:{},last:null};persist();document.querySelector('#reset-dialog').close();render();notify('Tu recorrido está listo para volver a empezar.');});
window.addEventListener('hashchange',()=>render());
render({focus:false});

window.lebenarPortal={mount:null,
 setAccess(value){portalAccess={...value,catalogReady:false};resources=[];render({focus:false,scroll:false});},
 setCatalog(items){if(!portalAccess.training)return;resources=items;portalAccess.catalogReady=true;render({focus:false,scroll:false});},
 catalogError(){portalAccess.catalogReady=false;resources=[];render({focus:false,scroll:false});},
 isTraining:()=>portalAccess.training&&portalAccess.catalogReady,
 getAccess:()=>({...portalAccess})
};
window.lebenarAccount={
 read:()=>JSON.parse(JSON.stringify(state)),
 clean(raw){const v=raw&&typeof raw==='object'?raw:{};const notes={};for(const k of [...ids,'proposito','accion'])if(typeof v.notes?.[k]==='string')notes[k]=v.notes[k].slice(0,3000);return {completed:[...new Set((Array.isArray(v.completed)?v.completed:[]).filter(x=>ids.has(x)))],saved:[...new Set((Array.isArray(v.saved)?v.saved:[]).filter(x=>ids.has(x)))],days:[...new Set((Array.isArray(v.days)?v.days:[]).filter(x=>Number.isInteger(x)&&x>=1&&x<=30))],notes,last:ids.has(v.last)?v.last:null};},
 set:value=>{state=window.lebenarAccount.clean(value);},
 render:()=>render({focus:false,scroll:false}),notify,
 attach:controller=>{accountController=controller;controller.panel();}
};
import('./portal-controller-20261025.js?v=guia-inicio-2').catch(()=>{document.querySelectorAll('[data-account-panel],#access-app').forEach(el=>el.textContent='No se pudo comprobar el acceso. Recargá para reintentar. Los materiales permanecen cerrados.');});

})();
